import{_ as a}from"./chunks/1776153628712.v2-8gJzS.js";import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.CdjpmwdR.js";const u=JSON.parse('{"title":"Logseq 迁移打分：五个维度、三条流水线","description":"基于五个维度评估旧笔记保留价值，并将笔记分入 A/B/C 三条迁移流水线，提供阈值、CSV 字段与校准步骤以便执行。","frontmatter":{"category":"domain","title":"Logseq 迁移打分：五个维度、三条流水线","date":"2026-04-13","description":"基于五个维度评估旧笔记保留价值，并将笔记分入 A/B/C 三条迁移流水线，提供阈值、CSV 字段与校准步骤以便执行。","tags":["domain","logseq","migration","knowledge-management"]},"headers":[],"relativePath":"blogs/2026/202604-logseq-scoring-overview.md","filePath":"blogs/2026/202604-logseq-scoring-overview.md"}'),d={name:"blogs/2026/202604-logseq-scoring-overview.md"};function s(l,e,c,r,p,h){return i(),o("div",null,[...e[0]||(e[0]=[n(`<p>在搭建好 Brains（LLM Wiki）之后，第一时间就是回去 Logseq 翻翻，看看有没有什么值得迁移的内容，榨取一遍剩余价值。在整理 Logseq 旧笔记时，最难的不是判断什么样的内容是值得留下的。为此，我设计了一个打分机制，让Agent在五个review维度上对内容进行打分，再按得分阈值分为三类笔记，最后批量的按流水线执行：立即吸收、延后总结、谨慎放弃。这样就不需要一个一个人为的判断，也不靠感觉决定去留了，更多是按一套能复查、能校准的流程走。</p><p>执行时按照：<strong>高价值、强相关、可复用的进 Lane A；暂时有价值但不值得立即精炼的进 Lane B；低分、重复、偏题的进 Lane C。</strong></p><h2 id="五个打分维度-分别在筛什么" tabindex="-1">五个打分维度，分别在筛什么 <a class="header-anchor" href="#五个打分维度-分别在筛什么" aria-label="Permalink to &quot;五个打分维度，分别在筛什么&quot;">​</a></h2><p>这套 rubric 对应五个字段：<code>goal_alignment</code>、<code>reusability</code>、<code>uniqueness</code>、<code>insight_density</code>、<code>maintainability</code>。它们看起来像指标，实际是在回答五个个性化问题。</p><table tabindex="0"><thead><tr><th>维度</th><th>主要在看什么</th><th>高分信号</th><th>低分信号</th></tr></thead><tbody><tr><td>goal_alignment</td><td>是否服务当前知识库目标</td><td>核心主题、可直接服务输出</td><td>偏题、与主线无关</td></tr><tr><td>reusability</td><td>能否跨场景复用</td><td>方法、规则、框架</td><td>一次性记录、强依赖上下文</td></tr><tr><td>uniqueness</td><td>是否重复劳动</td><td>独有表达、案例、结构</td><td>重复摘录、简写变体</td></tr><tr><td>insight_density</td><td>单位篇幅里是否有判断</td><td>结论、边界、建议</td><td>只有材料，没有提炼</td></tr><tr><td>maintainability</td><td>迁入后是否好维护</td><td>边界清楚、便于引用</td><td>主题散、维护成本高</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  score[五维打分] --&gt; check{是否重复 / 偏题?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check -- 是 --&gt; laneC[Lane C: Drop]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  check -- 否 --&gt; total{total_score &gt;= 18?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  total -- 否 --&gt; mid{11-17?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  total -- 是 --&gt; goal{goal_alignment &gt;= 4?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  goal -- 是 --&gt; laneA[Lane A: Ingest-Now]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mid -- 是 --&gt; laneB[Lane B: Summarize-Later]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  goal -- 否 --&gt; laneB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mid -- 否 --&gt; laneC</span></span></code></pre></div><h3 id="_1-goal-alignment-这条笔记是否服务当前知识库目标" tabindex="-1">1. goal_alignment：这条笔记是否服务当前知识库目标 <a class="header-anchor" href="#_1-goal-alignment-这条笔记是否服务当前知识库目标" aria-label="Permalink to &quot;1. goal_alignment：这条笔记是否服务当前知识库目标&quot;">​</a></h3><p>这一维看的是“它和当前迁移目标有没有关系”。迁移优先的是<strong>可复用的方法、框架和长期知识</strong>，所以核心主题天然比泛知识更容易得高分。最直接的判断方法，就是问一句：<strong>迁入后，能不能稳定服务当前知识库目标或后续输出？</strong></p><p>判断很简单：强相关就高，弱相关就低，无关就直接降级。</p><p>比如 <code>DDD.md</code>、<code>4+1 View Model.md</code>、<code>分析工具___MECE.md</code>、<code>架构治理.md</code> 本身就在高价值主题里，天然更贴近目标。相反，<code>多巴胺.md</code>、<code>虚数与复数.md</code>、<code>老头晒太阳.md</code> 这类内容，至少在当前目标下不占优先级。</p><h3 id="_2-reusability-这条笔记能不能跨场景复用" tabindex="-1">2. reusability：这条笔记能不能跨场景复用 <a class="header-anchor" href="#_2-reusability-这条笔记能不能跨场景复用" aria-label="Permalink to &quot;2. reusability：这条笔记能不能跨场景复用&quot;">​</a></h3><p>可复用性看的是“它能不能反复拿出来用”。至于我当时写得顺不顺，反而没那么重要。高分内容通常能脱离原始语境单独成立，描述的是方法、框架或判断规则，而不是一次性记录。像 DDD 拆解、架构风格对比、认知偏差总结，通常都更适合进入可复用知识层；零散问答、瞬时灵感、会议碎片则更适合先放进 Lane B。</p><p>迁移计划把 Lane B 设计成 <code>summary bundles</code>，承认的是一个简单事实：<strong>有些材料是“主题有价值，单条不值得精修”。</strong> 它们不该丢，但也不该占用 Lane A 的处理能力。</p><h3 id="_3-uniqueness-这条笔记是不是重复劳动" tabindex="-1">3. uniqueness：这条笔记是不是重复劳动 <a class="header-anchor" href="#_3-uniqueness-这条笔记是不是重复劳动" aria-label="Permalink to &quot;3. uniqueness：这条笔记是不是重复劳动&quot;">​</a></h3><p>独特性解决的是迁移里最常见的问题：看起来在积累，实际是在重复记录。所以计划里才会先建 <code>duplicate-clusters.md</code>，再判断一条笔记到底是 canonical source，还是重复变体。</p><table tabindex="0"><thead><tr><th>重复簇</th><th>典型问题</th><th>处理方式</th></tr></thead><tbody><tr><td>DDD family</td><td>同一主题多次展开</td><td>找 canonical source</td></tr><tr><td>architecture style comparisons</td><td>对比维度重复</td><td>合并成主题包</td></tr><tr><td>cognition micro-bias notes</td><td>碎片化但高度相似</td><td>汇总后再提炼</td></tr><tr><td>overlapping workshop Q&amp;A notes</td><td>问答内容互相重叠</td><td>保留最完整版本</td></tr></tbody></table><ul><li>如果一条笔记提供了别处没有的表达、案例或结构，它的独特性更高。</li><li>如果它只是另一条笔记的简写版、重复摘录版、局部展开版，它的独特性就应下降。</li></ul><p>这一步看不清，迁移后的知识库就会继续继承旧系统里的冗余。</p><h3 id="_4-insight-density-单位篇幅里有没有真正的判断" tabindex="-1">4. insight_density：单位篇幅里有没有真正的判断 <a class="header-anchor" href="#_4-insight-density-单位篇幅里有没有真正的判断" aria-label="Permalink to &quot;4. insight_density：单位篇幅里有没有真正的判断&quot;">​</a></h3><p>信息密度看的是“有效判断”有多少。高密度笔记通常有结论、有边界、有可执行建议；低密度内容则往往只有标题、概念或摘录，没有真正的提炼。这样的材料不是没用，但更像原材料，先留在 Lane B 的主题汇总里更合适。</p><p>迁移计划采用“先 synthesis，再 evidence，再 pages”的链路，本质上也是在提高 insight density：先合并原始材料，再提炼能站住脚的判断，最后才进入长期知识层。</p><h3 id="_5-maintainability-迁进去之后-未来好不好维护" tabindex="-1">5. maintainability：迁进去之后，未来好不好维护 <a class="header-anchor" href="#_5-maintainability-迁进去之后-未来好不好维护" aria-label="Permalink to &quot;5. maintainability：迁进去之后，未来好不好维护&quot;">​</a></h3><p>这一维决定知识库会不会越迁越重。好维护的内容，边界清楚、结构稳定、后续容易合并和引用；难维护的内容，通常语义发散、主题过宽、又强依赖当时上下文。计划要求 <code>inventory.csv</code> 记录 <code>primary_category</code>、<code>secondary_category</code>、<code>decision_reason</code>，就是为了提前把维护成本显式化。</p><h2 id="阈值规则-吞吐控制" tabindex="-1">阈值规则：吞吐控制 <a class="header-anchor" href="#阈值规则-吞吐控制" aria-label="Permalink to &quot;阈值规则：吞吐控制&quot;">​</a></h2><p>计划文档给出的阈值很明确：</p><ul><li><code>total_score &gt;= 18</code> 且 <code>goal_alignment &gt;= 4</code> → Lane A</li><li><code>11-17</code> → Lane B</li><li><code>&lt;=10</code> 或 duplicate / off-goal → Lane C</li></ul><p>我最在意的是 <strong>Lane A 额外要求 <code>goal_alignment &gt;= 4</code></strong>。这说明体系的优先级很明确：先看是否服务当前目标，再看综合价值。</p><h3 id="lane-a-立即吸收-不等以后" tabindex="-1">Lane A：立即吸收，不等以后 <a class="header-anchor" href="#lane-a-立即吸收-不等以后" aria-label="Permalink to &quot;Lane A：立即吸收，不等以后&quot;">​</a></h3><p>Lane A 对应 <code>Ingest-Now</code>。进入这一道，说明材料不仅整体价值高，而且和当前知识库目标强相关，值得立即投入精炼成本。</p><p>典型候选就是首波种子里的 DDD、架构、方法论、认知类核心笔记。它们会先进入 <code>raws/*-core-synthesis.md</code>、<code>raws/*-core-evidence.md</code>，再提升到 <code>pages/DDD.md</code>、<code>pages/架构模式.md</code>、<code>pages/问题分析与决策方法.md</code> 等正式页面。Lane A 的意思很简单：<strong>进入生产线。</strong></p><h3 id="lane-b-主题保留-但先做批处理" tabindex="-1">Lane B：主题保留，但先做批处理 <a class="header-anchor" href="#lane-b-主题保留-但先做批处理" aria-label="Permalink to &quot;Lane B：主题保留，但先做批处理&quot;">​</a></h3><p>Lane B 对应 <code>Summarize-Later</code>。总分落在 11-17，意味着它不是垃圾，也不是当前最该精修的对象。</p><p>这类内容的正确处理方式，是进入主题包。例如计划里的：</p><ul><li><code>raws/DDD-extended-notes-summary.md</code></li><li><code>raws/architecture-styles-comparison-summary.md</code></li><li><code>raws/cognitive-bias-and-heuristics-summary.md</code></li></ul><p>这背后的判断很实用：<strong>有价值，但价值主要体现在“成组后更有用”。</strong> 如果强行逐条精炼，成本会高于收益。</p><h3 id="lane-c-先记账-后复核" tabindex="-1">Lane C：先记账，后复核 <a class="header-anchor" href="#lane-c-先记账-后复核" aria-label="Permalink to &quot;Lane C：先记账，后复核&quot;">​</a></h3><p>Lane C 对应 <code>Drop</code>，但计划对它很克制。规则写的是 <code>&lt;=10</code> 或 duplicate / off-goal 可进 Lane C，同时又明确规定：<strong>任何物理删除都要等完整流程结束后的最终复核和显式确认。</strong></p><p>这点我很认同。Lane C 的意义是先停止继续投资。</p><p>也就是说，Lane C 更像一个带账本的冻结区：</p><ul><li>先记录它为什么被放弃。</li><li>先标记它是不是重复、偏题或低价值。</li><li>直到全量分类完成，再统一回看是否真的删除。</li></ul><p>这样能防止迁移前期因为判断标准还没稳定，就误删边界内容。</p><h2 id="执行流程-把打分、提炼、入库串成一条线" tabindex="-1">执行流程：把打分、提炼、入库串成一条线 <a class="header-anchor" href="#执行流程-把打分、提炼、入库串成一条线" aria-label="Permalink to &quot;执行流程：把打分、提炼、入库串成一条线&quot;">​</a></h2><p>要让这套东西真的跑起来，我最在意的其实不是“流程有多完整”，而是每一步能不能落到动作上。能不能回写。能不能复核。不能的话，前面说再多都没用。</p><ol><li>先把全量内容落到 <code>inventory.csv</code>。 <ul><li>这里不只是记文件名，还要把 <code>filename</code>、<code>primary_category</code>、<code>secondary_category</code>、<code>goal_alignment</code>、<code>reusability</code>、<code>uniqueness</code>、<code>insight_density</code>、<code>maintainability</code>、<code>total_score</code>、<code>lane</code>、<code>duplicate_cluster</code>、<code>decision_reason</code>、<code>status</code> 这些字段都准备好。这样后面每一次判断，处理的都是数据，不是印象。</li></ul></li><li>然后，用 Python 脚本把这份 CSV 包成一层可 CRUD 的操作面。 <ul><li>我不太想让 Agent 直接手改表，所以会把交互规则先写进 Prompt，Agent 只需要按规则去读、算、写。</li><li>说白了，就是先把规矩编码进去，再让它照着执行。这样少很多口头解释，也少很多“这次我觉得应该算进去”的偏差。</li></ul></li><li>接下来，按 20 条一组做打分标注。 <ul><li>每一组里，Agent 先分析内容，再调用 Python 脚本把分数、类别、lane、reason 写回 CSV。</li><li>第一轮的目标很简单：先分完，不急着精修。每批结束后，先生成分组结果，再把需要人工确认的条目单独列出来，尤其是边界样本、重复簇和争议项，人工过一遍。</li></ul></li><li>等初筛完成，再按同样的 20 条一组做内容提炼。 <ul><li>这一轮不再盯着分数，而是把能留下的内容压成当前知识库可接收的 <code>raws</code> 原始材料。</li><li>节奏还是一样：Agent 分析，脚本落盘，结果回看，必要项人工确认。这样提炼出来的，不是散笔记，而是已经过一轮筛选、可以继续进知识库加工的原料。</li></ul></li><li>最后，等所有内容都提炼完，再执行 <code>/kn-ingest</code>。<br> 这一步不是简单导入，而是把前面整理好的 <code>raws</code> 再消化一遍，真正变成当前知识库能直接用的新知识。到这里，打分、提炼、入库才算闭环。</li></ol><p><strong>最后，我就得到了 10 篇高度精炼、结构清晰、可复用的核心笔记（Lane A）</strong></p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p><img src="`+a+'" alt="Theme Wave 01"></p>',47)])])}const b=t(d,[["render",s]]);export{u as __pageData,b as default};
